/* Interface local: usa a mesma gravação recuperável do Financeiro. */
(()=>{'use strict';const C=MartinsClassificacao,G=MartinsGastosObras,P=MartinsPersistenciaRdo,$=id=>document.getElementById(id);if(!$('view-financeiro'))return;
const panel=document.createElement('section');panel.className='mf-box';panel.id='classificacao-despesas';panel.hidden=true;
panel.innerHTML=`<h2>Classificação de despesas por obra</h2><p>Homologação local com dados fictícios. O saldo continua na empresa até ser classificado. Propostas não alteram pagamentos ou conciliações.</p><label>Operação<select id="cd-company"></select></label><button id="cd-refresh">Atualizar pendências</button><button id="cd-export">Exportar saldo pendente CSV</button><p id="cd-status" role="status" aria-live="polite"></p><div id="cd-config"><h3>Vínculos por operação</h3><p>O Master libera cada usuário e vincula cada obra explicitamente. Não são definidos CNPJ ou sócios.</p><label>Usuário de Compras<select id="cd-user"></select></label><button id="cd-grant">Liberar Compras nesta operação</button><button id="cd-revoke">Revogar acesso</button><label>Obra existente<select id="cd-work-link"></select></label><button id="cd-link-work">Vincular obra à operação selecionada</button><p id="cd-links"></p></div><div id="cd-master"><h3>Despesas existentes ainda sem acompanhamento</h3><label>Despesa<select id="cd-expense"></select></label><label>Referências únicas (opcional, uma por linha: nfe:chave, cp:id, banco:id)<textarea id="cd-sources" rows="2"></textarea></label><button id="cd-register">Vincular despesa sem gerar novo lançamento</button><h3>Saldo não classificado</h3><div class="mf-scroll"><table><thead><tr><th>Despesa / revisão</th><th>Total</th><th>Classificado</th><th>Pendente</th><th>Aguardando Compras / aprovação</th></tr></thead><tbody id="cd-rows"></tbody></table></div><label>Despesa para trabalhar<select id="cd-selected"></select></label><label>Valor da parcela a encaminhar (R$)<input id="cd-amount" type="number" min="0.01" step="0.01"></label><label>Responsável de Compras<select id="cd-buyer"></select></label><label>Motivo / orientação<input id="cd-reason" maxlength="500"></label><button id="cd-send">Encaminhar parcela a Compras</button><button id="cd-reclassify">Substituir classificação pelo formulário abaixo</button><label>Referência da movimentação bancária<input id="cd-bank-ref" maxlength="500"></label><button id="cd-reconcile">Confirmar conciliação manual</button></div><h3>Fila de Compras e decisões do Master</h3><label>Tarefa<select id="cd-task"></select></label><p id="cd-task-detail"></p><h3>Proposta de classificação</h3><p>Preencha uma linha por obra. Para reclassificar, informe a distribuição completa desejada; o restante ficará pendente.</p><div id="cd-items"></div><button id="cd-add">Adicionar obra</button><label>Documentos PDF / PNG / JPEG (até 1 MB cada, 10 arquivos)<input id="cd-files" type="file" multiple accept="application/pdf,image/png,image/jpeg"></label><button id="cd-propose">Enviar proposta para aprovação</button><button id="cd-approve">Aprovar proposta</button><button id="cd-reject">Rejeitar proposta</button><button id="cd-withdraw">Retirar encaminhamento</button><details id="cd-history"><summary>Auditoria da operação</summary><pre id="cd-audit" style="white-space:pre-wrap"></pre></details>`;
const style=document.createElement('style');style.textContent='#classificacao-despesas textarea{width:100%;box-sizing:border-box;padding:10px;border:1px solid #cbd5e1;border-radius:8px}#classificacao-despesas pre{font-size:12px}#classificacao-despesas [hidden]{display:none!important}.cd-item{border:1px solid #cbd5e1;border-radius:8px;padding:10px;margin:10px 0}';document.head.append(style);$('view-financeiro').after(panel);
let base=null,ledger=null,busy=false,tasks=[];const money=n=>(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const msg=s=>{$('cd-status').textContent=s;};
function user(){const u=currentLoggedUser,session=JSON.parse(sessionStorage.getItem('cm_active_user')||'null');if(!u||!session||C.identity(u)!==C.identity(session)||u.perfil!==session.perfil||session.status==='Inativo')throw Error('Entre novamente com um usuário autorizado');return u;}
function data(){const s=P.snapshot(localStorage,C.KEY,C.initial());C.state(s.data);return s;}
function actor(s){const u=structuredClone(user());if(!C.master(u)){const grants=s.acessos?.[C.identity(u)]||[];u.empresasOperacionais=grants;u.perfil=grants.length?'Compras':u.perfil;}return u;}
function company(){return $('cd-company').value;}
function options(el,rows,placeholder='Selecione'){const previous=el.value;el.replaceChildren(new Option(placeholder,''));for(const [id,label] of rows)el.add(new Option(label,id));if(rows.some(([id])=>id===previous))el.value=previous;}
function users(){const rows=typeof getUsuariosDb==='function'?getUsuariosDb():[];return rows.filter(u=>u.status!=='Inativo');}
function works(s){return (s.obras||[]).filter(w=>Object.hasOwn(dadosObras,w.nome));}
function buyerOptions(s){return users().filter(u=>s.acessos?.[C.identity(u)]?.includes(company())).map(u=>[C.identity(u),u.nome||C.identity(u)]);}
function clearSensitive(){for(const id of ['cd-rows','cd-audit','cd-task-detail','cd-links'])$(id).replaceChildren();for(const id of ['cd-task','cd-selected','cd-expense','cd-buyer','cd-user','cd-work-link'])$(id).replaceChildren();tasks=[];base=null;ledger=null;}
function refresh(){clearSensitive();try{base=data();const u=actor(base.data),isMaster=C.master(u);$('cd-config').hidden=!isMaster;$('cd-master').hidden=!isMaster;$('cd-history').hidden=!isMaster;$('cd-export').hidden=!isMaster;for(const id of ['cd-approve','cd-reject','cd-withdraw','cd-reclassify','cd-reconcile'])$(id).hidden=!isMaster;const allowed=C.companies.filter(c=>isMaster||u.empresasOperacionais?.includes(c.id));options($('cd-company'),allowed.map(c=>[c.id,c.nome]));if(!company()&&allowed.length)$('cd-company').value=allowed[0].id;C.scope(u,company());const s=base.data;options($('cd-user'),users().filter(x=>C.identity(x)!==C.identity(u)).map(x=>[C.identity(x),x.nome||C.identity(x)]));options($('cd-work-link'),Object.keys(dadosObras).map(x=>[x,x]));options($('cd-buyer'),buyerOptions(s));$('cd-links').textContent=works(s).filter(w=>w.empresaId===company()).map(w=>w.nome).join(' · ');
if(isMaster){ledger=P.snapshot(localStorage,G.KEY,[]);G.assertRows(ledger.data);const name=C.companies.find(c=>c.id===company()).nome;options($('cd-expense'),ledger.data.filter(d=>d.tipo==='despesa'&&d.status!=='cancelado'&&d.empresa===name&&!s.despesas.some(x=>x.id===d.id)).map(d=>[d.id,d.descricao+' · '+money(d.valorCentavos)]));const rows=C.report(s,ledger.data,u,company());options($('cd-selected'),rows.filter(d=>!d.semVinculo).map(d=>[d.id,d.descricao+' · pendente '+money(d.pendente)]));for(const d of rows){const tr=document.createElement('tr');for(const text of [d.descricao+(d.semVinculo?' / vincular antes de classificar':' / v'+d.revisao)+(d.originalAlterado?' — original alterado: conferir':''),money(d.total),money(d.total-d.pendente),money(d.pendente),money(d.reservado)]){const td=document.createElement('td');td.textContent=text;tr.append(td);}$('cd-rows').append(tr);}$('cd-audit').textContent=s.historico.filter(h=>h.empresaId===company()).map(h=>h.em+' · '+h.por+' · '+h.acao+' · '+(h.despesaId||'configuração')+' · '+h.motivo).join('\n');}
tasks=C.queue(s,u,company());options($('cd-task'),tasks.map(t=>[t.id,t.estado+' · '+money(t.centavos)+' · '+t.responsavel]));showTask();msg('Atualizado. Nenhuma operação bancária executada.');}catch(e){clearSensitive();msg(e.message);}}
function showTask(){const t=tasks.find(t=>t.id===$('cd-task').value);$('cd-task-detail').textContent=t?JSON.stringify({parcela:money(t.centavos),orientacao:t.motivo,estado:t.estado,proposta:t.proposta,documentos:t.documentos?.map(d=>d.nome)},null,2):'Selecione uma tarefa';if(t)for(const doc of t.documentos||[]){const link=document.createElement('button');link.type='button';link.textContent='Baixar '+doc.nome;link.onclick=()=>{const [head,encoded]=doc.conteudo.split(','),bytes=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:head.slice(5,head.indexOf(';'))})),a=document.createElement('a');a.href=url;a.download=doc.nome;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('cd-task-detail').append(link);}}
function add(){const box=document.createElement('div');box.className='cd-item mf-grid';const fields=[['obra','Obra','select'],['valor','Valor (R$)','number'],['categoria','Categoria','select'],['centroCusto','Centro de custo','text'],['fornecedor','Fornecedor','text'],['materiais','Materiais / serviços','text'],['finalidade','Finalidade','text']];for(const [key,label,type] of fields){const l=document.createElement('label');l.textContent=label;const input=document.createElement(type==='select'?'select':'input');input.dataset.field=key;if(type==='select'){const rows=key==='obra'?works(base?.data||{}).filter(w=>w.empresaId===company()).map(w=>w.nome):G.categories;options(input,rows.map(v=>[v,v]));}else {input.type=type;input.maxLength=500;if(type==='number'){input.step='0.01';input.min='0.01';}}l.append(input);box.append(l);}const remove=document.createElement('button');remove.textContent='Remover linha';remove.onclick=()=>box.remove();box.append(remove);$('cd-items').append(box);}
const items=()=>[...$('cd-items').children].map(box=>Object.fromEntries([...box.querySelectorAll('[data-field]')].map(el=>[el.dataset.field,el.value])));
async function mutate(operation){if(busy||!base)return;busy=true;const expected=base.raw;try{await P.withLock(navigator.locks,async()=>{const fresh=data();if(fresh.raw!==expected)throw Error('Dados alterados; atualize antes de salvar. Formulário preservado.');const u=actor(fresh.data);C.scope(u,company());const l=P.snapshot(localStorage,G.KEY,[]);const result=await operation(fresh.data,l.data,u);const current=actor(data().data);if(C.identity(current)!==C.identity(u)||JSON.stringify(current)!==JSON.stringify(u))throw Error('Sessão ou permissões alteradas durante a operação');const writes=[{key:C.KEY,expected:fresh.raw,value:result.state}];if(result.ledger)writes.push({key:G.KEY,expected:l.raw,value:result.ledger});else writes.push({key:G.KEY,expected:l.raw,value:l.data});P.commit(localStorage,writes,{actor:C.identity(u)});});refresh();$('cd-items').replaceChildren();$('cd-files').value='';msg('Salvo com auditoria. Nenhum pagamento, baixa ou transferência executado.');}catch(e){msg(e.message);}finally{busy=false;}}
function run(action){const task=tasks.find(t=>t.id===$('cd-task').value),taskAction=['propor','aprovar','rejeitar','retirar'].includes(action),id=taskAction?task?.despesaId:$('cd-selected').value;const revision=base?.data.despesas.find(d=>d.id===id)?.revisao;const input={tarefaId:task?.id,valor:$('cd-amount').value,responsavel:$('cd-buyer').value,motivo:$('cd-reason').value,referencia:$('cd-bank-ref').value,itens:items()};const files=[...$('cd-files').files];mutate(async(s,rows,u)=>{input.documentos=[];if(action==='propor'){if(files.length>10||files.some(f=>f.size>1000000))throw Error('Limite: 10 documentos de até 1 MB');for(const f of files){const bytes=new Uint8Array(await f.arrayBuffer());if(!(bytes[0]===37&&bytes[1]===80&&bytes[2]===68&&bytes[3]===70||bytes[0]===137&&bytes[1]===80&&bytes[2]===78&&bytes[3]===71||bytes[0]===255&&bytes[1]===216&&bytes[2]===255))throw Error('Conteúdo do arquivo não corresponde a PDF / PNG / JPEG');const conteudo=await new Promise((resolve,reject)=>{const r=new FileReader;r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f);});input.documentos.push({nome:f.name,conteudo});}}return C.command(s,rows,id,revision,u,action,input,works(s));});}
$('cd-register').onclick=()=>mutate((s,rows,u)=>({state:C.register(s,rows,$('cd-expense').value,company(),u,{fontes:$('cd-sources').value.split('\n').map(x=>x.trim()).filter(Boolean)})}));
function configure(kind){mutate((s,rows,u)=>{if(!C.master(u))throw Error('Exclusivo do Master');const n=structuredClone(s);if(kind==='obra'){const nome=$('cd-work-link').value;if(!Object.hasOwn(dadosObras,nome))throw Error('Obra indisponível');if(n.obras?.some(w=>w.nome===nome&&w.empresaId!==company()))throw Error('Obra já pertence a outra operação; exige revisão específica');n.obras=(n.obras||[]).filter(w=>w.nome!==nome);n.obras.push({nome,empresaId:company()});}else{const id=$('cd-user').value;if(!users().some(x=>C.identity(x)===id))throw Error('Usuário indisponível');n.acessos||={};n.acessos[id]=(n.acessos[id]||[]).filter(e=>e!==company());if(kind==='grant')n.acessos[id].push(company());}n.historico.push({empresaId:company(),acao:'configurar_'+kind,por:C.identity(u),em:new Date().toISOString(),motivo:kind==='obra'?$('cd-work-link').value:$('cd-user').value});return {state:n};});}
$('cd-grant').onclick=()=>configure('grant');$('cd-revoke').onclick=()=>configure('revoke');$('cd-link-work').onclick=()=>configure('obra');
for(const [id,action] of [['send','encaminhar'],['propose','propor'],['approve','aprovar'],['reject','rejeitar'],['withdraw','retirar'],['reclassify','reclassificar'],['reconcile','conciliar']])$('cd-'+id).onclick=()=>run(action);
$('cd-add').onclick=add;$('cd-task').onchange=showTask;$('cd-refresh').onclick=refresh;$('cd-company').onchange=()=>{$('cd-items').replaceChildren();$('cd-files').value='';refresh();};
$('cd-export').onclick=()=>{try{const s=data().data,u=actor(s),rows=C.report(s,P.snapshot(localStorage,G.KEY,[]).data,u,company()).filter(d=>d.pendente);const cell=v=>'"'+String(v).replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"';const csv='\uFEFF'+[['Empresa','Despesa','Total centavos','Pendente centavos','Reservado centavos'],...rows.map(d=>[company(),d.descricao,d.total,d.pendente,d.reservado])].map(r=>r.map(cell).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='despesas-nao-classificadas.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){msg(e.message);}};
function open(){panel.hidden=false;refresh();panel.scrollIntoView({block:'start'});}
const btn=document.createElement('button');btn.textContent='Classificação de despesas';btn.type='button';btn.onclick=open;$('view-financeiro').querySelector('nav').append(btn);
const old=window.navegarParaSecao;window.navegarParaSecao=function(name,sub){panel.hidden=true;const result=old.call(this,name==='classificacao'?'financeiro':name,sub);if(name==='classificacao'){ $('view-financeiro').classList.add('hidden');open();}return result;};
const menu=document.createElement('button');menu.textContent='Classificação / fila de Compras';menu.type='button';menu.onclick=()=>window.navegarParaSecao('classificacao');$('fin-drawer')?.append(menu);
window.addEventListener('storage',()=>{clearSensitive();msg('Os dados mudaram em outra aba. Atualize para continuar.');});
})();
